CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT,product_no INTEGER UNIQUE NOT NULL,name TEXT NOT NULL,price INTEGER DEFAULT 0,category TEXT DEFAULT '',tags TEXT DEFAULT '',affiliate_url TEXT NOT NULL,youtube_url TEXT DEFAULT '',thumbnail_url TEXT DEFAULT '',description TEXT DEFAULT '',featured INTEGER DEFAULT 0,active INTEGER DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS requests (id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,product_name TEXT NOT NULL,product_url TEXT DEFAULT '',message TEXT DEFAULT '',contact TEXT DEFAULT '',created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
